class Solution {
    public List<List<Long>> splitPainting(int[][] segments){
        TreeMap<Integer,Long> difference=new TreeMap<>();
        for(int[] segment:segments){
            difference.merge(segment[0],(long)segment[2],Long::sum);
            difference.merge(segment[1],-(long)segment[2],Long::sum);
        }
        List<List<Long>> answer=new ArrayList<>();
        long active=0;
        int previous=0;
        boolean started=false;
        for(Map.Entry<Integer,Long> entry:difference.entrySet()){
            int position=entry.getKey();
            if(started&&active!=0&&previous<position)answer.add(Arrays.asList((long)previous,(long)position,active));
            active+=entry.getValue();
            previous=position;
            started=true;
        }
        return answer;
    }
}

